# Generated by Claude (Claude Code).
"""t-SNE of PeakCNN's 32 features on the cubic test set (seed 12345), drawn like the PCA/LDA/UMAP images.
Usage: python tsne_features.py <project dir> <run dir> <out png> [subset size]
  subset size: random functions of the test set to embed (seed 0); default all 51,200."""
import json, sys, time, warnings
from pathlib import Path
import numpy as np
import torch, torch_directml
from sklearn.manifold import TSNE
from matplotlib import rc_context
from matplotlib.figure import Figure
from matplotlib.lines import Line2D

project, run, out = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
sys.path.insert(0, str(project))
import data  # noqa: E402
from model import NUM_SAMPLES, PeakCNN  # noqa: E402
from plot import AXIS, RC, SURFACE, TEXT_PRIMARY, TEXT_SECONDARY  # noqa: E402
warnings.filterwarnings("ignore")
data.WARP, data.MIN_KNOT_DISTANCE = "cubic", 0.05
N, SEED = 51_200, 12345
f, y = data.generate_batch(N, NUM_SAMPLES, np.random.default_rng(SEED))
rng = np.random.default_rng(SEED)
lab = rng.integers(0, 3, N)
pats = []
for label in lab:
    ps = data.PATTERNS[label]
    p = ps[rng.integers(len(ps))]
    data.sample_params(p, rng)
    pats.append(p)
pats = np.array(pats)
dev = torch_directml.device()
cfg = json.loads((run / "config.json").read_text())
model = PeakCNN(NUM_SAMPLES, cfg["channels"])
model.load_state_dict(torch.load(run / "model.pt", weights_only=True))
model.to(dev).eval()
feats, preds = [], []
with torch.no_grad():
    for k in range(0, N, 1024):
        h = torch.flatten(model.features(torch.from_numpy(f[k:k + 1024]).to(dev).unsqueeze(1)), 1)
        feats.append(h.cpu().numpy()); preds.append(model.classifier(h).argmax(1).cpu().numpy())
X = np.concatenate(feats)
subset = int(sys.argv[4]) if len(sys.argv) > 4 else N
keep = np.sort(np.random.default_rng(0).choice(N, subset, replace=False)) if subset < N else np.arange(N)
X, y, pats, preds = X[keep], y[keep], pats[keep], [np.concatenate(preds)[keep]]
N = len(keep)
print(f"features {X.shape}; model accuracy {np.mean(np.concatenate(preds) == y):.3%}")
start = time.perf_counter()
E = TSNE(n_components=2, perplexity=30, init="pca", learning_rate="auto", random_state=0, n_jobs=-1).fit_transform(X)
print(f"t-SNE done in {(time.perf_counter() - start) / 60:.1f} min")
np.savez_compressed(Path(out).with_suffix(".npz"), E=E, labels=y, patterns=pats, pred=np.concatenate(preds))

SHADES = {"": "#1f3fbf", "V": "#6f8fff", "P": "#0b6b1f", "VP": "#1f9f3a", "PV": "#4cc35c", "VPV": "#93df8f",
          "PVP": "#8b0000", "VPVP": "#c81e1e", "PVPV": "#f05050", "VPVPV": "#ff9c8c"}
order = np.random.default_rng(0).permutation(N)
with rc_context(RC):
    fig = Figure(figsize=(11, 8), dpi=160, facecolor=SURFACE)
    ax = fig.add_subplot()
    ax.set_facecolor(SURFACE)
    ax.scatter(E[order, 0], E[order, 1], s=1.4, c=np.array([SHADES[p] for p in pats])[order], linewidths=0,
               alpha=0.8, rasterized=True)
    ax.set_aspect("equal", adjustable="datalim")
    ax.set_xticks([]); ax.set_yticks([])
    ax.set_xlabel("t-SNE 1 (no units)", color=TEXT_SECONDARY); ax.set_ylabel("t-SNE 2 (no units)", color=TEXT_SECONDARY)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(AXIS)
    handles = []
    for cls, name in ((0, "0 peaks"), (1, "1 peak"), (2, "2 peaks")):
        handles.append(Line2D([], [], linestyle="none", label=name))
        for p, col in SHADES.items():
            if p.count("P") == cls:
                handles.append(Line2D([], [], marker="o", linestyle="none", markersize=7, color=col,
                                      label=f"  {p or '(none)'}  ({int(np.sum(pats == p)):,})"))
    leg = ax.legend(handles=handles, loc="upper left", bbox_to_anchor=(1.01, 1.0), frameon=False,
                    handletextpad=0.4, borderaxespad=0)
    for text, h in zip(leg.get_texts(), handles):
        heading = h.get_marker() in (None, "None", "")
        text.set_color(TEXT_PRIMARY if heading else TEXT_SECONDARY)
        if heading:
            text.set_fontweight("semibold")
    fig.suptitle("t-SNE of the 32 features of the cubic-warp model", x=0.08, y=0.965, ha="left", fontsize=13,
                 fontweight="semibold", color=TEXT_PRIMARY)
    fig.text(0.08, 0.925, "test functions (seed 12345, cubic warp, minimum distance 0.05) · run "
             f"{run.name} · {N:,} random functions · perplexity 30, PCA initialization, seed 0 · colour: true peak count, shade: pattern",
             ha="left", fontsize=9, color=TEXT_SECONDARY)
    fig.subplots_adjust(left=0.08, right=0.8, top=0.88, bottom=0.08)
    fig.savefig(out, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)
print("saved", out)
